<?php
declare(strict_types=1); require_once __DIR__ . '/../includes/auth.php'; require_auth(); require_once __DIR__ . '/../includes/csrf.php'; require_once __DIR__ . '/../config/database.php'; require_csrf();
$user=current_user($conn);$title=post_string('title',50);$description=post_string('description',500);$receiver=(int)($_POST['receiver_id']??0);$remarks=post_string('remarks',500);
if(!$user||$title===''||$description===''||$receiver<1){flash('error','Title, description, and recipient are required.');redirect('documents/create.php');}
if ($receiver === (int) $user['id']) { flash('error', 'Choose another recipient.'); redirect('documents/create.php'); }
$eligible=$conn->prepare("SELECT id FROM dr_users WHERE id=? AND status <> 'Inactive' LIMIT 1");$eligible->bind_param('i',$receiver);$eligible->execute();if(!fetch_one($eligible)){flash('error','Choose an active recipient.');redirect('documents/create.php');}
$department=$user['department'];$author=(int)$user['id'];$conn->begin_transaction();try{$count=$conn->prepare('SELECT COUNT(d.id) AS total FROM dr_documents d JOIN dr_users u ON u.id=d.author WHERE u.department=? FOR UPDATE');$count->bind_param('s',$department);$count->execute();$total=(int)(fetch_one($count)['total']??0);$tracking=date('Ym-').str_pad((string)($total+1),4,'0',STR_PAD_LEFT).'-'.$author;$now=date('Y-m-d H:i:s');$open='open';$document=$conn->prepare('INSERT INTO dr_documents (id_track,title,description,author,datecreated,status) VALUES (?,?,?,?,?,?)');$document->bind_param('sssiss',$tracking,$title,$description,$author,$now,$open);$document->execute();$pending='Pending';$route=$conn->prepare('INSERT INTO dr_logs (id_track,sender,receiver,status,date,remarks) VALUES (?,?,?,?,?,?)');$route->bind_param('siisss',$tracking,$author,$receiver,$pending,$now,$remarks);$route->execute();$conn->commit();flash('success','Document '.$tracking.' was created and routed.');redirect('dashboard.php');}catch(Throwable $error){$conn->rollback();error_log($error->getMessage());flash('error','Unable to create the document. Please try again.');redirect('documents/create.php');}
